source.style.css:
:root{

    --black:#0b0b0b;
    --black2:#151515;
    --white:#ffffff;
    --gold:#d4af37;
    --gray:#9d9d9d;

    --transition:.4s ease;
    --radius:12px;

}



*{
    margin:0;
    padding:0;
    box-sizing:border-box;
}

html{
    scroll-behavior:smooth;
    scroll-padding-top:calc(var(--header-height, 100px) + 24px);
}

body{

    font-family:'Poppins',sans-serif;
    background:var(--black);
    color:var(--white);
    overflow-x:hidden;

}

img{
    width:100%;
    display:block;
}

a{
    text-decoration:none;
    color:inherit;
}

ul{
    list-style:none;
}

section{
    padding:100px 8%;
}

h1,h2,h3,h4,h5{
    font-weight:500;
}

/*==========================================
    HEADER
==========================================*/

header{

    position:fixed;
    top:0;
    left:0;

    width:100%;

    padding:20px 8%;

    display:flex;
    justify-content:space-between;
    align-items:center;

    background:rgba(0,0,0,.45);

    backdrop-filter:blur(12px);

    transition:.35s ease;

    z-index:1000;

}

.logo h2, .home-page .logo-title{

    font-family:'Bebas Neue',sans-serif;

    font-size:40px;

    letter-spacing:2px;

    color:#fff;

}

nav ul{

    display:flex;

    align-items:center;

    gap:38px;

}

nav ul li a::after{

    content:"";

    position:absolute;

    left:0;

    bottom:-8px;

    width:0;

    height:2px;

    background:var(--gold);

    transition:.35s;

}

nav ul li a:hover::after,

nav ul li a.active::after{

    width:100%;

}

nav ul li a.active{

    color:var(--gold);

}

nav ul li a{

    position:relative;

    font-size:15px;

    color:#ddd;

    font-weight:500;

    transition:.35s;

}

nav ul li a:hover{

    color:var(--gold);

}

.btn{

    display:inline-flex;

    justify-content:center;

    align-items:center;

    padding:13px 30px;

    border:2px solid var(--gold);

    border-radius:40px;

    color:var(--gold);

    font-weight:600;

    transition:.35s;

}

.btn:hover{

    background:var(--gold);

    color:#000;

}

/*================ MENU TOGGLE ================*/

.menu-toggle{

    display:none;

    width:34px;
    padding:0;
    border:0;
    background:transparent;

    cursor:pointer;

}

.menu-toggle span{

    display:block;

    width:100%;

    height:3px;

    margin:7px 0;

    background:#fff;

    transition:.35s;

}

/*=========================================================
    NAVBAR RESPONSIVE
=========================================================*/

/*========== Sticky Header ==========*/

header.scrolled{

    padding:14px 8%;

    background:rgba(8,8,8,.95);

    box-shadow:0 8px 25px rgba(0,0,0,.35);

}

/*========== Large Tablet ==========*/

@media(max-width:992px){

    header{backdrop-filter:none; -webkit-backdrop-filter:none;}

    .menu-toggle{

        display:block;

        z-index:2001;

    }

    header > .btn{

        display:none;

    }

    nav{

        position:fixed;

        top:0;

        right:0;
        transform:translateX(100%);
        visibility:hidden;

        width:min(320px, 88vw);
        padding:100px 24px 32px;
        overflow-y:auto;

        height:100vh;
        height:100dvh;

        background:#0d0d0d;

        display:flex;

        justify-content:center;

        align-items:center;

        transition:.45s ease;

        z-index:2000;

        border-left:1px solid rgba(255,255,255,.08);

    }

    nav.active{

        transform:translateX(0);
        visibility:visible;

    }

    nav ul{

        flex-direction:column;

        gap:35px;

    }

    nav ul li a{

        font-size:22px;

    }

}

/*========== Mobile ==========*/

@media(max-width:576px){

    header{

        padding:18px 6%;

    }

    .logo h2, .home-page .logo-title{

        font-size:32px;

    }

}

/*========== Hamburger Animation ==========*/

.menu-toggle.active span:nth-child(1){

    transform:translateY(10px) rotate(45deg);

}

.menu-toggle.active span:nth-child(2){

    opacity:0;

}

.menu-toggle.active span:nth-child(3){

    transform:translateY(-10px) rotate(-45deg);

}

body.menu-open{

    position:fixed;
    width:100%;
    overflow:hidden;

}

/*=========================================================
    NAVBAR FINAL POLISH
=========================================================*/

/*========== Background Overlay ==========*/

.nav-overlay{

    position:fixed;

    inset:0;

    background:rgba(0,0,0,.65);

    backdrop-filter:blur(4px);

    opacity:0;

    visibility:hidden;

    transition:.35s;

    z-index:999;

}

.nav-overlay.active{

    opacity:1;

    visibility:visible;

}

/*========== Menu Item Animation ==========*/

@media(max-width:992px){

    nav ul li{

        opacity:0;

        transform:translateX(40px);

        transition:.45s;

    }

    nav.active ul li{

        opacity:1;

        transform:translateX(0);

    }

    nav.active ul li:nth-child(1){

        transition-delay:.08s;

    }

    nav.active ul li:nth-child(2){

        transition-delay:.16s;

    }

    nav.active ul li:nth-child(3){

        transition-delay:.24s;

    }

    nav.active ul li:nth-child(4){

        transition-delay:.32s;

    }

    nav.active ul li:nth-child(5){

        transition-delay:.40s;

    }

}

/* Hero grows with its content; padding reserves the fixed header and indicator. */
.hero{
    position:relative;
    min-height:100vh;
    min-height:100svh;
    display:flex;
    align-items:center;
    justify-content:center;
    padding:calc(var(--header-height, 100px) + 40px) 8% 115px;
    text-align:center;
    background:linear-gradient(rgba(0,0,0,.65),rgba(0,0,0,.75)),url("images/hero.jpg") center/cover;
    background-attachment:fixed;
}
.hero-content{position:relative; z-index:2; width:100%; max-width:900px; min-width:0;}
.hero-content .hero-tag{color:var(--gold); letter-spacing:5px; margin-bottom:20px; font-size:14px;}
.hero-content h1{font-family:'Bebas Neue',sans-serif; font-size:105px; line-height:.96; letter-spacing:3px; margin-bottom:15px;}
.hero-content h2{font-size:34px; font-weight:300; color:#ddd; margin-bottom:30px; letter-spacing:4px;}
.hero-content .hero-description{width:100%; max-width:700px; margin:0 auto; font-size:18px; line-height:1.9; color:#cfcfcf; letter-spacing:normal;}
.hero-stats{display:flex; justify-content:center; gap:70px; margin-top:40px;}
.hero-stats h3, .hero-stats .hero-stat-value{font-size:48px; color:var(--gold); margin-bottom:5px;}
.hero-stats span{font-size:15px; color:#bbb; letter-spacing:2px;}
@media(max-width:1100px){
    .hero-content h1{font-size:70px; line-height:1.07;}
    header{padding-left:5%; padding-right:5%;}
    nav ul{gap:24px;}
}
@media(max-width:768px){
    .hero{align-items:flex-start; background-attachment:scroll; padding:calc(var(--header-height, 90px) + 32px) 6% 110px;}
    .hero-content h1{font-size:50px; line-height:1.1;}
    .hero-content h2{font-size:22px; letter-spacing:2px;}
    .hero-content .hero-description{font-size:16px; line-height:1.8;}
    .hero-stats{gap:30px; flex-wrap:wrap; margin-top:32px;}
}
@media(max-width:500px){
    .hero-content h1{font-size:38px; letter-spacing:1px;}
    .hero-content h2{font-size:18px; letter-spacing:1px;}
    .hero-content .hero-tag{font-size:11px; letter-spacing:3px;}
    .hero-content .hero-description{font-size:14px; line-height:1.7;}
    .hero-stats{gap:24px;}
    .hero-stats h3, .hero-stats .hero-stat-value{font-size:36px;}
}

/*==========================================
    HERO
==========================================*/

.overlay{

    position:absolute;

    inset:0;

    background:rgba(0,0,0,.65);

}

.buttons{

    margin-top:45px;

    display:flex;

    justify-content:center;

    gap:20px;

}

.primary-btn{

    padding:15px 40px;

    background:var(--gold);

    color:#000;

    border-radius:40px;

    transition:.4s;

    font-weight:600;

}

.primary-btn:hover{

    transform:translateY(-5px);

}

.secondary-btn{

    padding:15px 40px;

    border:2px solid white;

    border-radius:40px;

    transition:.4s;

}

.secondary-btn:hover{

    background:white;

    color:black;

}

/*==========================================
    ABOUT
==========================================*/

.about{

    display:grid;

    grid-template-columns:1fr 1fr;

    gap:70px;

    align-items:center;

}

.about .left img{

    border-radius:15px;

}

.right h5, .home-page .right .home-eyebrow{

    color:var(--gold);

    letter-spacing:4px;

    margin-bottom:15px;

}

.right h2{

    font-family:'Bebas Neue';

    font-size:55px;

    line-height:60px;

    margin-bottom:25px;

}

.right p{

    color:#bdbdbd;

    line-height:1.8;

    margin-bottom:40px;

}

.stats{

    display:flex;

    gap:50px;

}

.stats div{

    text-align:center;

}

.stats h3{

    font-size:48px;

    color:var(--gold);

    margin-bottom:10px;

}

.stats p{

    margin:0;

    color:#ccc;

}

/*==========================================
    COMMON TITLES
==========================================*/

section h5, .home-page .home-eyebrow{

    color:var(--gold);

    letter-spacing:4px;

    margin-bottom:12px;

}

.section-heading{
    text-align:center;
    margin-bottom:70px;
}
.section-heading .section-tag{
    display:inline-block;
    color:var(--gold);
    letter-spacing:4px;
    font-size:14px;
    margin-bottom:15px;
}
.section-heading h2{
    font-size:52px;
    color:#fff;
}

section h2{

    font-family:'Bebas Neue';

    font-size:60px;

    margin-bottom:45px;

}

/*==========================================
    END OF PART 1
    PART 2 STARTS BELOW THIS
==========================================*/

/*==========================================
    SERVICES
==========================================*/

/* Studio components: shared by the redesigned sections only. */
.home-approach{
    display:grid;
    grid-template-columns:1fr 1.15fr;
    gap:80px;
    align-items:start;
    background:linear-gradient(125deg,#17150f,#0c0c0c 60%);
    border-block:1px solid #3a3324;
}
.approach-intro h2{font-size:clamp(44px,5vw,72px); line-height:1.05; margin:18px 0 24px;}
.approach-intro > p{color:#c6c3bb; font-size:15px; line-height:1.9; max-width:410px;}
.approach-graphic{margin-top:38px; padding:24px 0 0; border-top:1px solid #443b28;}
.approach-graphic > svg{display:block; width:100%; height:auto; margin:8px 0; overflow:visible;}
.approach-frame{fill:none; stroke:#6d5b31; stroke-width:1;}
.approach-track,.approach-progress{fill:none; stroke-width:2;}
.approach-track{stroke:#776235;}
.approach-progress{stroke:#e2c263; stroke-dasharray:100; stroke-dashoffset:calc(100 - var(--approach-progress,0)); transition:stroke-dashoffset .4s ease;}
.approach-node circle{fill:#14130f; stroke:#9c8346; stroke-width:2; transition:fill .25s,stroke .25s;}
.approach-node text{fill:#c6c3bb; text-anchor:middle; font-family:'Bebas Neue',sans-serif; font-size:20px;}
.approach-node.is-active circle{fill:#e2c263; stroke:#e2c263;}
.approach-node.is-active text{fill:#e2c263;}
.approach-graphic .approach-status{color:#e2c263; font-size:12px; letter-spacing:1px; line-height:1.8; margin:0; min-height:22px;}
.approach-steps{border-top:1px solid #4a4030;}
.approach-step{position:relative; border-bottom:1px solid #4a4030;}
.approach-step summary{
    display:grid;
    grid-template-columns:36px minmax(0,1fr) 20px;
    align-items:center;
    gap:20px;
    min-height:94px;
    padding:20px 8px;
    cursor:pointer;
    list-style:none;
    transition:background .2s;
}
.approach-step summary::-webkit-details-marker{display:none;}
.approach-number{font-family:'Bebas Neue',sans-serif; color:#e2c263; font-size:28px;}
.approach-step-title{display:block; font-size:20px; line-height:1.4; color:#f4f0e7;}
.approach-step-subtitle{display:block; color:#c6c3bb; font-size:12px; line-height:1.7; margin-top:5px;}
.approach-step summary > svg{width:20px; height:20px; fill:none; stroke:#e2c263; stroke-width:1.5; transition:transform .25s;}
.approach-step[open] summary > svg{transform:rotate(45deg);}
.approach-step summary:hover,.approach-step summary:focus-visible{background:#d4af370a;}
.approach-step summary:focus-visible{outline:2px solid #efcf75; outline-offset:4px;}
.approach-step[open]::before{content:""; position:absolute; top:24px; left:-12px; width:2px; height:46px; background:#e2c263;}
.approach-detail{padding:0 28px 24px 64px; min-height:140px;}
.approach-detail p{color:#c6c3bb; font-size:14px; line-height:1.9; margin:0;}
.approach-detail .approach-question{color:#e2c263; font-size:12px; line-height:1.8; margin-top:16px;}
.home-approach.approach-enhanced:not(.is-in-view) .approach-track{stroke-dasharray:100; stroke-dashoffset:100;}
.home-approach.approach-enhanced .approach-track{stroke-dasharray:100; stroke-dashoffset:0; transition:stroke-dashoffset .7s ease;}
.home-approach.approach-enhanced:not(.is-in-view) .approach-step{opacity:0; transform:translateY(6px);}
.home-approach.approach-enhanced .approach-step{transition:opacity .35s ease,transform .35s ease;}
.home-approach.is-in-view .approach-step:nth-child(2){transition-delay:.05s;}
.home-approach.is-in-view .approach-step:nth-child(3){transition-delay:.1s;}
.home-approach.is-in-view .approach-step:nth-child(4){transition-delay:.15s;}
@media(max-width:992px){.home-approach{grid-template-columns:1fr; gap:40px;}.approach-graphic{max-width:480px;}}
@media(max-width:576px){.approach-step summary{gap:14px; grid-template-columns:30px minmax(0,1fr) 20px;}.approach-step-title{font-size:18px;}.approach-detail{padding-left:52px; padding-right:8px; min-height:180px;}.approach-step[open]::before{left:-8px;}}

.studio-section{color:#f4f0e7; padding:100px 8%;}
.studio-heading{display:flex; justify-content:space-between; align-items:flex-end; gap:40px; margin-bottom:48px;}
.studio-kicker{display:block; color:var(--gold); font-size:11px; font-weight:500; letter-spacing:2.5px; line-height:1.6;}
.studio-heading h2{font-family:'Bebas Neue',sans-serif; font-size:clamp(44px,5vw,72px); line-height:1.02; letter-spacing:1px; margin:16px 0 0;}
.studio-heading > p{max-width:390px; color:#c6c3bb; font-size:15px; line-height:1.9;}
.studio-grid{display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:28px;}
.studio-card{display:flex; flex-direction:column; min-width:0; background:#171717; border:1px solid #343129; border-radius:6px; overflow:hidden; transition:border-color .3s,box-shadow .3s;}
.studio-card-image{aspect-ratio:16/9; overflow:hidden; background:#202020;}
.studio-card-image img{height:100%; object-fit:cover;}
.studio-card-body{display:flex; flex-direction:column; flex:1; padding:28px;}
.studio-card h3{font-family:'Bebas Neue',sans-serif; font-size:34px; line-height:1.1; letter-spacing:.5px; margin:14px 0;}
.studio-card p{color:#c6c3bb; font-size:14px; line-height:1.85; margin-bottom:28px;}
.text-link{display:inline-flex; align-items:center; gap:20px; color:#e2c263; font-size:13px; font-weight:500; padding:10px 0; width:fit-content; margin-top:auto; border-bottom:1px solid #756330; transition:color .25s,border-color .25s;}
.text-link span{font-size:20px; line-height:1;}
.text-link:hover{color:#fff3c3; border-color:#fff3c3;}
.studio-card:focus-within{border-color:var(--gold);}
a:focus-visible,button:focus-visible{outline:2px solid #efcf75; outline-offset:5px;}
@media(hover:hover) and (pointer:fine){.studio-card:hover{border-color:#a58b40; box-shadow:0 16px 40px #0004;}}
.services.studio-section{background:linear-gradient(145deg,#141414,#0d0d0d); text-align:left; opacity:1; transform:none;}

/* Home service showcase: native disclosures work with touch, keyboard and without JS. */
.services [data-service-showcase] .studio-card-image{position:relative;}
.showcase-frame{height:100%; transform:scale(1); transition:transform .45s ease;}
.services [data-service-showcase] .studio-card-image::after{
    content:"";
    position:absolute;
    inset:auto 0 0;
    height:3px;
    background:var(--gold);
    transform:scaleX(.18);
    transform-origin:left;
    transition:transform .4s ease;
}
.showcase-disclosure{margin:0 0 20px; border-block:1px solid #48402d;}
.showcase-disclosure summary{
    display:flex;
    justify-content:space-between;
    align-items:center;
    gap:16px;
    min-height:48px;
    padding:12px 0;
    color:#e2c263;
    font-size:13px;
    line-height:1.6;
    cursor:pointer;
    list-style:none;
}
.showcase-disclosure summary::-webkit-details-marker{display:none;}
.showcase-disclosure summary:focus-visible{outline:2px solid #efcf75; outline-offset:4px;}
.showcase-disclosure summary svg{width:20px; height:20px; flex-shrink:0; fill:none; stroke:currentColor; stroke-width:1.5; transition:transform .25s;}
.showcase-disclosure[open] summary svg{transform:rotate(180deg);}
.showcase-detail{padding:6px 0 22px;}
.showcase-detail .studio-kicker{font-size:10px; letter-spacing:1.5px; margin-bottom:10px;}
.studio-card .showcase-detail p{font-size:13px; margin:0;}
.showcase-disclosure[open] .showcase-detail{animation:showcase-reveal .28s ease-out;}
.services [data-service-showcase] .studio-card-body > p{margin-bottom:0;}
.services [data-service-showcase]:has(details[open]){border-color:#a58b40;}
.services [data-service-showcase]:has(details[open]) .showcase-frame{transform:scale(1.035);}
.services [data-service-showcase]:has(details[open]) .studio-card-image::after{transform:scaleX(1);}
@media(hover:hover) and (pointer:fine){
    .services [data-service-showcase]:hover .showcase-frame{transform:scale(1.035);}
    .services [data-service-showcase]:hover .studio-card-image::after{transform:scaleX(1);}
}
@keyframes showcase-reveal{
    from{opacity:0; transform:translateY(6px);}
    to{opacity:1; transform:translateY(0);}
}
@media(max-width:1100px){.studio-section{padding:90px 6%;}.studio-grid{grid-template-columns:repeat(2,minmax(0,1fr));}}
@media(max-width:768px){.studio-section{padding:72px 6%;}.studio-heading{display:block; margin-bottom:32px;}.studio-heading > p{margin-top:22px;}.studio-grid{grid-template-columns:1fr; gap:24px;}.studio-card-body{padding:26px;}}


/*==========================================
    PORTFOLIO
==========================================*/

.portfolio{
    background:var(--black);
    text-align:center;
}

.gallery{
    display:grid;
    grid-template-columns:repeat(3,1fr);
    gap:25px;
    margin-top:60px;
}

.item{
    overflow:hidden;
    border-radius:15px;
    position:relative;
}

.item img{
    height:320px;
    object-fit:cover;
    transition:.6s;
}

.item::before{
    content:'';
    position:absolute;
    inset:0;
    background:rgba(0,0,0,.35);
    opacity:0;
    transition:.4s;
    z-index:1;
}

.item:hover::before{
    opacity:1;
}

.item:hover img{
    transform:scale(1.12);
}

/* Homepage gallery triggers retain the existing .item geometry and effects. */
.project-trigger{
    display:block;
    width:100%;
    min-width:0;
    padding:0;
    border:0;
    background:transparent;
    color:inherit;
    font:inherit;
    cursor:pointer;
}

/* Native dialog top layer keeps the cinematic viewer above the fixed header. */
body.project-viewer-open{position:fixed; width:100%; overflow:hidden;}
.project-lightbox{
    position:fixed;
    inset:0;
    width:100%;
    max-width:none;
    height:100vh;
    height:100dvh;
    max-height:none;
    margin:0;
    padding:0;
    border:0;
    background:#050505;
    color:#f4f0e7;
    font-family:'Poppins',sans-serif;
    overflow:hidden;
    overscroll-behavior:contain;
    isolation:isolate;
}
.project-lightbox[open]{animation:viewer-open .24s ease-out;}
.project-lightbox::backdrop{background:rgba(0,0,0,.96); animation:viewer-open .24s ease-out;}
.viewer-background{position:absolute; inset:0; overflow:hidden; pointer-events:none;}
.viewer-background-layer{
    position:absolute;
    inset:-32px;
    background-position:center;
    background-size:cover;
    filter:blur(22px) brightness(.24);
    opacity:0;
    transition:opacity .35s ease;
}
.viewer-background-layer.is-visible{opacity:1;}
.viewer-layout{
    position:relative;
    display:grid;
    grid-template-rows:auto minmax(0,1fr) auto;
    gap:20px;
    height:100%;
    padding:max(24px,env(safe-area-inset-top)) max(24px,env(safe-area-inset-right)) max(24px,env(safe-area-inset-bottom)) max(24px,env(safe-area-inset-left));
}
.viewer-topbar{display:flex; justify-content:space-between; align-items:center; gap:24px; min-width:0;}
.viewer-meta{min-width:0;}
.viewer-meta p{margin:0;}
.viewer-counter{color:#e2c263; font-size:13px; font-weight:500; letter-spacing:3px; font-variant-numeric:tabular-nums;}
.viewer-title{color:#f4f0e7; font-size:14px; line-height:1.6; max-width:60vw; overflow-wrap:anywhere;}
.viewer-stage{display:grid; place-items:center; min-width:0; min-height:0; touch-action:pan-y pinch-zoom;}
.viewer-image{
    display:block;
    width:auto;
    height:auto;
    max-width:100%;
    max-height:100%;
    object-fit:contain;
    opacity:1;
    transform:scale(1);
    transition:opacity .18s ease,transform .25s ease;
    box-shadow:0 20px 70px #0008;
    user-select:none;
    -webkit-user-select:none;
}
.project-lightbox[data-state="loading"] .viewer-image{opacity:0; transform:scale(.985);}
.viewer-loading,.viewer-error{grid-area:1/1; max-width:360px; text-align:center; color:#e5decc; font-size:14px; line-height:1.8;}
.viewer-image{grid-area:1/1;}
.viewer-error p{margin-bottom:20px;}
.viewer-navigation{display:flex; justify-content:center; gap:20px;}
.viewer-control{
    display:inline-flex;
    align-items:center;
    justify-content:center;
    gap:14px;
    min-width:48px;
    min-height:48px;
    padding:12px 20px;
    border:1px solid #a68b42;
    border-radius:4px;
    background:rgba(10,10,10,.65);
    color:#e2c263;
    font:inherit;
    font-size:13px;
    line-height:1.4;
    cursor:pointer;
    transition:background .2s,border-color .2s,color .2s;
}
.viewer-close{padding:12px; flex-shrink:0;}
.viewer-control svg{width:22px; height:22px; fill:none; stroke:currentColor; stroke-width:1.5;}
.viewer-control:hover{background:#242014; border-color:#e2c263; color:#fff0bc;}
.viewer-control:focus-visible{outline:2px solid #efcf75; outline-offset:4px;}
.project-lightbox [hidden]{display:none;}
@keyframes viewer-open{from{opacity:0;}to{opacity:1;}}
@media(max-width:768px){
