/*==========================================
    CTA
==========================================*/

.cta{
    text-align:center;
    background:linear-gradient(135deg,#111,#1d1d1d);
}

.cta h2{
    margin-bottom:35px;
    font-size:65px;
}

/* Homepage-only invitation; no generic CTA or magnetic-button classes. */
.home-project-cta{
    position:relative;
    isolation:isolate;
    overflow:hidden;
    background:#10100d;
    text-align:center;
    border-block:1px solid #3c3524;
}
.home-project-cta::before{
    content:"";
    position:absolute;
    inset:0;
    z-index:-1;
    background:radial-gradient(ellipse at var(--cta-spot-x,50%) var(--cta-spot-y,35%),rgba(212,175,55,.12),transparent 65%),linear-gradient(135deg,#17150f,#0a0a0a);
    pointer-events:none;
}
.project-cta-frame{position:absolute; inset:24px; width:calc(100% - 48px); height:calc(100% - 48px); fill:none; stroke:#8a713b; stroke-width:1; opacity:.65; pointer-events:none;}
.project-cta-content{max-width:1000px; margin:20px auto;}
.project-cta-content h2{font-family:'Bebas Neue',sans-serif; font-size:clamp(46px,7vw,100px); line-height:1.05; letter-spacing:1px; margin:22px 0 28px; text-wrap:balance;}
.project-cta-content h2 span{color:#e2c263;}
.project-cta-content > p{max-width:570px; margin:0 auto; color:#c6c3bb; font-size:15px; line-height:1.9;}
.project-cta-actions{display:flex; justify-content:center; align-items:center; gap:32px; margin-top:36px;}
.project-cta-primary,.project-cta-secondary{display:inline-flex; justify-content:center; align-items:center; gap:20px; min-height:52px; font-size:14px; font-weight:500; line-height:1.5;}
.project-cta-primary{padding:16px 28px; border:1px solid #d4af37; border-radius:4px; color:#111; background:#d4af37; transition:background .25s,border-color .25s,box-shadow .25s;}
.project-cta-primary:hover,.project-cta-primary:focus-visible{background:#e2c263; border-color:#e2c263; box-shadow:0 0 24px #d4af3718;}
.project-cta-primary svg,.project-cta-secondary svg{width:22px; height:22px; fill:none; stroke:currentColor; stroke-width:1.5; flex-shrink:0;}
.project-cta-secondary{position:relative; padding:14px 0; color:#e2c263;}
.project-cta-secondary::after{content:""; position:absolute; bottom:5px; left:0; width:100%; height:1px; background:currentColor; transform:scaleX(.25); transform-origin:left; transition:transform .3s ease;}
.project-cta-secondary:hover::after,.project-cta-secondary:focus-visible::after{transform:scaleX(1);}
.project-cta-primary:focus-visible,.project-cta-secondary:focus-visible{outline:2px solid #efcf75; outline-offset:6px;}
.home-project-cta.cta-enhanced:not(.is-in-view) .project-cta-content{opacity:0; transform:translateY(8px);}
.home-project-cta.cta-enhanced .project-cta-content{transition:opacity .5s ease,transform .5s ease;}
@media(max-width:576px){
    .project-cta-frame{inset:16px; width:calc(100% - 32px); height:calc(100% - 32px);}
    .project-cta-content{margin:16px auto;}
    .project-cta-content h2{letter-spacing:.5px;}
    .project-cta-actions{flex-direction:column; gap:16px; margin-top:28px;}
    .project-cta-primary{width:100%; max-width:300px; padding-inline:20px;}
}

