/* About story: a framed image and an editorial reading column. */
.about-story{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.1fr);align-items:center;gap:clamp(40px,6vw,90px);background:#0a0a0a;}
.about-story .story-image{position:relative;min-width:0;padding:12px;border:1px solid #71603b;}
.about-story .story-image::before,.about-story .story-image::after{content:"";position:absolute;width:28px;height:28px;pointer-events:none;}
.about-story .story-image::before{top:-1px;left:-1px;border-top:2px solid #d4af37;border-left:2px solid #d4af37;}
.about-story .story-image::after{bottom:-1px;right:-1px;border-bottom:2px solid #d4af37;border-right:2px solid #d4af37;}
.about-story .story-image-media{overflow:hidden;aspect-ratio:1;clip-path:inset(0);transition:clip-path .8s cubic-bezier(.2,.7,.2,1);}
.about-story .story-image img{width:100%;height:auto;display:block;transform:scale(1);transition:transform .8s ease;}
.about-story .story-image-caption{display:block;margin:14px 0 2px;font-size:9px;letter-spacing:3px;color:#bcb3a0;line-height:1.8;}
.about-story .story-content{min-width:0;max-width:620px;}
.about-story .section-tag{display:block;color:#d4af37;letter-spacing:3px;margin-bottom:20px;font-size:11px;font-weight:500;}
.about-story .story-content h2{font-family:'Bebas Neue',sans-serif;font-size:clamp(40px,4.5vw,68px);line-height:1.08;letter-spacing:.7px;color:#f4f0e7;margin:0;max-width:540px;text-wrap:balance;}
.about-story .story-divider{display:block;width:80px;height:1px;background:#b69851;margin:28px 0;transform-origin:left;transition:transform .65s ease .15s;}
.about-story .story-content p{color:#c8c5bd;line-height:1.95;margin:0 0 20px;font-size:15px;}
.about-story .story-work-link{display:inline-flex;align-items:center;justify-content:center;gap:22px;min-height:52px;margin-top:12px;padding:14px 28px;border:1px solid #d4af37;border-radius:40px;background:#d4af37;color:#111;font-size:14px;font-weight:600;transition:background .25s,border-color .25s;}
.about-story .story-work-link svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.5;transition:transform .25s;}
.about-story .story-work-link:hover,.about-story .story-work-link:focus-visible{background:#e2c263;border-color:#e2c263;}
.about-story .story-work-link:hover svg,.about-story .story-work-link:focus-visible svg{transform:translateX(3px);}
.about-story .story-work-link:focus-visible{outline:2px solid #efcf75;outline-offset:6px;}
.about-story .story-entrance{transition:opacity .6s ease,transform .6s ease;}
.about-story .story-content h2{transition-delay:.08s;}
.about-story .story-content p:nth-of-type(1){transition-delay:.16s;}
.about-story .story-content p:nth-of-type(2){transition-delay:.24s;}
.about-story .story-work-link{transition:opacity .6s ease .32s,transform .6s ease .32s,background .25s,border-color .25s;}
.about-story.story-enhanced:not(.show):not(:focus-within) .story-image-media{clip-path:inset(0 10% 100% 0);}
.about-story.story-enhanced:not(.show):not(:focus-within) .story-image img{transform:scale(1.05);}
.about-story.story-enhanced:not(.show):not(:focus-within) .story-entrance{opacity:0;transform:translateY(12px);}
.about-story.story-enhanced:not(.show):not(:focus-within) .story-divider{transform:scaleX(0);}
@media(hover:hover) and (pointer:fine){.about-story.show .story-image:hover img{transform:scale(1.025);}}
@media(max-width:992px){.about-story{grid-template-columns:1fr;gap:36px;}.about-story .story-image{width:100%;max-width:520px;}.about-story .story-content{max-width:680px;}}
