@media(prefers-reduced-motion:reduce){.about-story.show .story-image:hover img,.about-story .story-work-link:hover svg,.about-story .story-work-link:focus-visible svg{transform:none;} .about-story .story-image-media,.about-story .story-image img,.about-story .story-entrance,.about-story .story-divider,.about-story .story-work-link svg{transition:none;}.about-story.story-enhanced .story-image-media{clip-path:none;}.about-story.story-enhanced .story-image img,.about-story.story-enhanced .story-entrance,.about-story.story-enhanced .story-divider{transform:none;opacity:1;}}

