    .approach-step summary > svg,.approach-node circle{transition:none;}
    .project-lightbox[open],.project-lightbox::backdrop{animation:none;}
    .project-lightbox .viewer-background-layer,.project-lightbox .viewer-control{transition:none;}
    .project-lightbox[data-state] .viewer-image{transform:none; transition:none;}
    .showcase-frame,.showcase-disclosure summary svg,
    .services [data-service-showcase] .studio-card-image::after{transition:none;}
    .showcase-disclosure[open] .showcase-detail{animation:none;}
    .services [data-service-showcase]:hover .showcase-frame,
    .services [data-service-showcase]:has(details[open]) .showcase-frame{transform:none;}
    html{scroll-behavior:auto;}
    header,nav,nav ul li,.nav-overlay,.menu-toggle span,
    .btn,.primary-btn,.secondary-btn,.text-link,.studio-card,
    .enquiry-button,.enquiry-field input,.enquiry-field select,.enquiry-field textarea{transition:none;}
    .card,.item,.about img,.right,.cta,.scroll-down span::before{animation:none;}
